delete from public.units where id not in ('s1-arv', 's1-voz', 's1-har', 's2-cdv', 's2-hmz', 's2-tex', 's3-for', 's3-txt', 's3-ctp', 's3-har', 's4-rea', 's4-cor', 's4-pop', 's4-gos', 's4-qtm', 's4-acp', 's4-mpb', 's4-prf') and not exists (select 1 from public.lessons l where l.unit_id = units.id);
